code='''def transform(grid):
    a = [row[:] for row in grid]
    h, w = len(a), len(a[0])
    bg = max(set(x for row in a for x in row), key=lambda x: sum(row.count(x) for row in a))

    def runs(vals):
        out=[]; i=0
        while i < len(vals):
            if vals[i] == bg:
                i += 1; continue
            color=vals[i]; j=i+1
            while j < len(vals) and vals[j] == color: j += 1
            if j-i >= 2: out.append((i,j,color))
            i=j
        return out

    # Find matching runs on opposite borders. The long edge runs are the paired emitters.
    choices=[]
    lr1, lr2 = runs([a[r][0] for r in range(h)]), runs([a[r][w-1] for r in range(h)])
    for x in lr1:
        for y in lr2:
            if x[2] == y[2] and x[1]-x[0] == y[1]-y[0]: choices.append(('h',x,y))
    tb1, tb2 = runs(a[0]), runs(a[h-1])
    for x in tb1:
        for y in tb2:
            if x[2] == y[2] and x[1]-x[0] == y[1]-y[0]: choices.append(('v',x,y))
    if not choices: return a
    # Pick the paired boundary bars with the most combined cells.
    axis, first, second = max(choices, key=lambda q: (q[1][1]-q[1][0], q[1][2]))
    length=first[1]-first[0]
    for k in range(length):
        if axis == 'h':
            r1, r2 = first[0]+k, second[0]+k
            rays=[[(r1,c) for c in range(1,w-1)], [(r2,c) for c in range(w-2,0,-1)]]
            starts=[(r1,0),(r2,w-1)]
        else:
            c1, c2 = first[0]+k, second[0]+k
            rays=[[(r,c1) for r in range(1,h-1)], [(r,c2) for r in range(h-2,0,-1)]]
            starts=[(0,c1),(h-1,c2)]
        found=[]
        for cells in rays:
            hit=None
            for idx, (r,c) in enumerate(cells):
                val=a[r][c]
                if val != bg and val != first[2]:
                    hit=(idx,r,c,val); break
            found.append(hit)
        colors=[x[3] for x in found if x is not None]
        if not colors: continue
        for si,cells in enumerate(rays):
            hit=found[si]
            color=hit[3] if hit else colors[0]
            limit=hit[0] if hit else len(cells)
            for r,c in cells[:limit]:
                if a[r][c] == bg: a[r][c]=color
            if hit:
                _,r,c,_=hit; a[r][c]=4
    return a
'''
